{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "A questão pede que você descubra o que cada palavra pequena faz no texto. Para cada item, pergunte a que classe a palavra pertence e a que ela se liga. 'Que' pode ser pronome relativo, que retoma um termo anterior, ou conjunção, que só liga orações. 'Se' pode indeterminar o sujeito (não dizer quem faz a ação), apassivar o verbo ou ser parte do verbo pronominal.",
   "motivo": "Explica 'indeterminar' na primeira aparição, para aluno de 17 anos."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["referente", "o termo do texto que a palavra retoma ou substitui"],
    ["pronome relativo", "palavra como 'que' ou 'o qual' que retoma um termo já citado e liga duas orações"],
    ["conjunção", "palavra que só liga orações e não retoma nenhum termo"],
    ["locução conjuntiva", "conjunção formada por mais de uma palavra, como 'para que'"],
    ["finalidade", "ideia de objetivo: a oração diz para quê a ação é feita"],
    ["indeterminação do sujeito", "o sujeito existe, mas não é identificado; a frase não diz quem faz a ação"],
    ["verbo pronominal", "verbo que sempre vem com pronome (arrepender-se, assemelhar-se); o 'se' faz parte dele"],
    ["conclusiva", "relação em que a segunda ideia é o resultado da primeira"]
   ],
   "motivo": "Termos técnicos usados na resolução (pronome relativo, conjunção, locução conjuntiva, finalidade) não estavam explicados."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "'Para que' é locução conjuntiva: introduz a oração de finalidade. 'Ele próprio' é o sujeito de 'acabe', não o termo que o 'que' retoma. Trocar por 'o qual' dá frase sem sentido. Logo, a afirmativa é falsa.",
   "motivo": "Frases mais claras e conectivo de conclusão."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "'Tratar' pede a preposição 'de' (tratar de algo). 'De uma técnica de atenção' é o complemento do verbo, então não pode ser sujeito. O 'se' indetermina o sujeito e não retoma 'técnica de atenção'. A afirmativa é falsa.",
   "motivo": "Deixa claro por que o complemento não pode ser referente do 'se'."
  }
 ],
